from pathlib import Path
from html.parser import HTMLParser
from hashlib import sha256
import json

class Homepage(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.text = []
        self.link = None
        self.hidden = 0

    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
        if tag == 'a' and not self.hidden:
            self.link = [dict(attrs).get('href', ''), []]

    def handle_endtag(self, tag):
        if tag in ('script', 'style') and self.hidden:
            self.hidden -= 1
        if tag == 'a' and self.link is not None:
            href, label = self.link
            self.links.append({'href': href, 'label': ' '.join(label)})
            self.link = None

    def handle_data(self, data):
        text = ' '.join(data.split())
        if text and not self.hidden:
            self.text.append(text)
            if self.link is not None:
                self.link[1].append(text)

source = Path('products/distribution/sqlite-newsletter/raw/dbweekly-home.html')
raw = source.read_bytes()
digest = sha256(raw).hexdigest()
assert digest == '25dce07c2617b9f2cc2ee8afe5a009b3656dabac1c40731643ba7f00cba519a2'
page = Homepage()
page.feed(raw.decode('utf-8', errors='replace'))
terms = ('submit', 'suggest', 'curat', 'editor', 'contact', 'tips', 'archive', 'issue', 'sqlite', 'sponsor', 'advertis', 'ai-generated')
links = [item for item in page.links if any(term in (item['href'] + ' ' + item['label']).lower() for term in terms)]
excerpts = []
for index, text in enumerate(page.text):
    if any(term in text.lower() for term in terms):
        excerpts.append(' '.join(page.text[max(0, index-1):index+2])[:700])
report = {'source': 'https://dbweekly.com/', 'receipt': 'TASK-179562600200', 'sha256': digest, 'links': links[:40], 'excerpts': list(dict.fromkeys(excerpts))[:30], 'scope': 'Homepage pointers only. Editorial eligibility, current issue fit and submission permission require reading the original relevant pages.'}
out = source.parent.parent / 'director-homepage-extract.json'
out.write_text(json.dumps(report, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
assert json.loads(out.read_text(encoding='utf-8')) == report
print(json.dumps({'artifact': str(out), 'candidate_links': len(links), 'excerpt_matches': len(excerpts)}))
